package dev.chungjungsoo.gptmobile.presentation.ui.voice
import dev.chungjungsoo.gptmobile.data.voice.*
import kotlinx.coroutines.*
import org.junit.Assert.*
import org.junit.Test
class ExtractedVoiceRoutingTest {
 @Test fun restorationKeepsRetainedFactoryLanguageAndStrictLocalRequirement()=runBlocking {
  val screen=ExtractedVoiceRouting(this)
  screen.translationOutput=VoiceTranslationPlayback(VoiceTranslationTarget("en-US","fr-FR","estelle"),factory("accepted-estelle"))
  screen.preferencesApplied=false
  screen.attach()
  assertEquals(listOf("accepted-estelle"),screen.kokoroOutput!!.configured)
  assertEquals("fr-FR",screen.systemAudio.synthesisLanguageTag)
  assertTrue(screen.audio.requireLocalOutput)
  screen.preferencesApplied=true
  screen.translationMode=true
  screen.attach()
  assertEquals(listOf("accepted-estelle","accepted-estelle"),screen.kokoroOutput.configured)
 }
 @Test fun manualFrenchReplayHonorsSavedPolicyAfterCaptureTranslationIsDisabled()=runBlocking {
  val screen=ExtractedVoiceRouting(this)
  screen.readResponse(VoiceMessageIdentity(2,"run"),"Bonjour.")
  coroutineContext.job.children.toList().joinAll()
  assertEquals("fr-FR",screen.translationOutput?.target?.targetLanguage)
  assertEquals("estelle",screen.translationOutput?.target?.voiceId)
  assertTrue(screen.audio.requireLocalOutput)
  assertEquals(listOf("Bonjour."),screen.session.replies)
  assertEquals(VoiceResponsePolicy.REPLY_AMERICAN_ENGLISH,screen.model.voiceReplyPolicy)
 }
 @Test fun automaticFrenchReplyUsesSavedPolicyWithCaptureTranslationDisabled()=runBlocking {
  val screen=ExtractedVoiceRouting(this)
  screen.translationFactories["fr-FR:estelle"]=factory("cached-estelle")
  assertTrue(screen.automatic(VoiceMessageReply(VoiceMessageIdentity(2,"run"),"Bonjour.",false)))
  assertEquals("cached-estelle",screen.translationOutput?.factory?.identity)
  assertTrue(screen.audio.requireLocalOutput)
 }
 @Test fun missingAcceptedMetadataCannotConsumeOrReplayThroughOrdinaryVoice()=runBlocking {
  val screen=ExtractedVoiceRouting(this)
  screen.model.agentRunsById.value=emptyMap()
  assertFalse(screen.automatic(VoiceMessageReply(VoiceMessageIdentity(2,"run"),"Bonjour.",false)))
  screen.readResponse(VoiceMessageIdentity(2,"run"),"Bonjour.")
  coroutineContext.job.children.toList().joinAll()
  assertTrue(screen.session.replies.isEmpty())
  assertTrue(screen.session.failures.single().contains("still unavailable"))
 }
 @Test fun explicitOrdinaryPolicyClearsRetainedOutputAndPreservesFutureRequestPolicy()=runBlocking {
  val screen=ExtractedVoiceRouting(this)
  screen.translationOutput=VoiceTranslationPlayback(VoiceTranslationTarget("en-US","fr-FR","estelle"),factory("accepted-estelle"))
  screen.model.groupedMessages.value=SourceGroup(listOf(SourceMessage(1,1,listOf(SourceTimeline(null)))))
  assertTrue(screen.automatic(VoiceMessageReply(VoiceMessageIdentity(2,"run"),"Hello.",false)))
  assertNull(screen.translationOutput)
  assertFalse(screen.audio.requireLocalOutput)
  assertEquals("en-US",screen.systemAudio.synthesisLanguageTag)
  assertEquals(VoiceResponsePolicy.REPLY_AMERICAN_ENGLISH,screen.model.voiceReplyPolicy)
 }
 @Test fun retainedTranslationIsSupportedWhenOrdinaryBackendCannotSynthesizeItsPreferences()=runBlocking {
  val screen=ExtractedVoiceRouting(this)
  screen.backend.backend=KindPort(false)
  screen.translationOutput=VoiceTranslationPlayback(VoiceTranslationTarget("en-US","fr-FR","estelle"),factory("accepted-estelle"))
  screen.applyAudioConfiguration()
  assertTrue(screen.audio.synthesisSupported)
  assertTrue(screen.audio.requireLocalOutput)
  assertEquals("fr-FR",screen.systemAudio.synthesisLanguageTag)
  assertEquals(VoiceResponsePolicy.REPLY_AMERICAN_ENGLISH,screen.model.voiceReplyPolicy)
 }
 @Test fun translatedHistoryEnablesReplayWhenOnlyTheMultilingualPackIsReady()=runBlocking {
  val screen=ExtractedVoiceRouting(this)
  screen.backend.ready=false
  assertTrue(screen.available())
  screen.translationModel=null
  assertFalse(screen.available())
 }
 @Test fun legacyOrdinaryReplayDoesNotRequireAnAgentRun()=runBlocking {
  val screen=ExtractedVoiceRouting(this)
  screen.translationMode=true
  screen.readResponse(VoiceMessageIdentity(2,""),"Hello.")
  assertEquals(listOf("Hello."),screen.session.replies)
  assertNull(screen.translationOutput)
 }
}

package dev.chungjungsoo.gptmobile.presentation.ui.voice
import dev.chungjungsoo.gptmobile.data.voice.*
import java.io.File
import kotlinx.coroutines.*
import kotlinx.coroutines.flow.MutableStateFlow
internal fun factory(name:String)=object:VoicePhraseEngineFactory {override val identity=name;override fun create(directory:File,lexicon:String,threads:Int):VoicePhraseEngine=error("No engine opens in routing tests")}
internal data class SourceTimeline(val voiceResponsePolicy:VoiceResponsePolicy?)
internal data class SourceMessage(val id:Int,val chatId:Int,val timeline:List<SourceTimeline>)
internal data class SourceGroup(val userMessages:List<SourceMessage>)
internal data class RunPort(val chatId:Int,val assistantMessageId:Int,val userMessageId:Int)
internal class ReplyModelPort {var voiceReplyPolicy=VoiceResponsePolicy.REPLY_AMERICAN_ENGLISH;val agentRunsById=MutableStateFlow(mapOf("run" to RunPort(1,2,1)));val groupedMessages=MutableStateFlow(SourceGroup(listOf(SourceMessage(1,1,listOf(SourceTimeline(VoiceResponsePolicy.TRANSLATE_FRENCH))))))}
internal data class RoomPort(val id:Int=1)
internal class AudioPort {var requireLocalOutput=false;var synthesisSupported=false}
internal class SystemAudioPort {var synthesisLanguageTag="en-US"}
internal class TuningPort {fun apply(value:Unit,language:String){}}
internal class OutputPort {val configured=mutableListOf<String>();fun configureEngine(factory:VoicePhraseEngineFactory){configured+=factory.identity}}
internal class KindPort(val compatible:Boolean=true) {fun forSynthesis(synthesis:Unit)=if(compatible)this else KindPort()}
internal class BackendPort {val factory=factory("ordinary-pocket");var backend=KindPort();var loaded=true;var ready=true;fun speechModelReady(model:Unit)=ready}
internal class BackendOwnerPort {val calls=mutableListOf<Pair<String,String>>();suspend fun translationFactory(language:String,voice:String):VoicePhraseEngineFactory {calls+=language to voice;return factory("translation-$voice")}}
internal class SessionPort {val replies=mutableListOf<String>();val failures=mutableListOf<String>();var owner=0;fun holdAudio(value:Boolean){};fun access(enabled:Boolean,permission:Boolean,resumed:Boolean){};fun beginMessage(id:String,manual:Boolean,diagnosticRunId:String,includeDetails:Boolean)=true;fun reply(id:String,text:String){replies+=text};fun fail(reason:String,reportFailure:Boolean){failures+=reason};fun pause(reason:String){owner++};fun playbackPreparationOwner()=owner;fun ownsPlaybackPreparation(value:Int)=value==owner}
internal class Lifecycle {enum class State {RESUMED;fun isAtLeast(other:State)=this==other};var currentState=State.RESUMED}
internal class ExtractedVoiceRouting(val settingsScope:CoroutineScope) {
 val backend=BackendPort();val backendOwner=BackendOwnerPort();val model=ReplyModelPort();val room=RoomPort()
 val session=SessionPort();val audio=AudioPort();val systemAudio=SystemAudioPort();val kokoroOutput:OutputPort?=OutputPort();val tuningConfiguration=TuningPort();val tuning=Unit
 var translationMode=false;var translationPair=VoiceTranslationPair();var translationOutput:VoiceTranslationPlayback?=null
 val translationFactories=mutableMapOf<String,VoicePhraseEngineFactory>();var translationReplayGeneration=0
 var enabled=true;var preferencesApplied=true;var loaded=true;var roomReady=true;var permission=true
 val lifecycle=Lifecycle();var settingsOpen=false;var routeOpen=false;val benchmarkOwnership=MutableStateFlow<Any?>(null)
 val playback=VoiceMessagePlayback();var manualMessage=false;var activeMessage:VoiceMessageIdentity?=null
 var ordinaryProfile=requireNotNull(MediaPipeSpeechVoices.forVoice("alba"));val synthesis=Unit;val kokoroModel=Unit
 var translationModel:LocalVoiceModelState?=LocalVoiceModelState(LocalVoiceModelStatus.READY);var benchmarkRunning=false;var translationPlaybackNeeded=true
 fun activeSpeechProfile()=ordinaryProfile
 fun pauseCapture() {translationReplayGeneration++}
 fun retainMessage(identity:VoiceMessageIdentity){}
 fun translationVoiceKey(target:VoiceTranslationTarget)="${target.targetLanguage}:${target.voiceId}"
    fun outputSpeechProfile() = if (translationMode && translationOutput != null) {
        MediaPipeSpeechVoices.forVoice(translationOutput!!.target.voiceId) ?: activeSpeechProfile()
    } else {
        activeSpeechProfile()
    }
    fun applyTranslationOutput(target: VoiceTranslationTarget, factory: VoicePhraseEngineFactory) {
        translationOutput = VoiceTranslationPlayback(target, factory)
        // Configure the destination before any translated phrase can open an audio stream.
        kokoroOutput?.configureEngine(factory)
        audio.synthesisSupported = true
        // A different system voice cannot fulfill this turn's selected language/voice pair.
        audio.requireLocalOutput = true
        systemAudio.synthesisLanguageTag = target.targetLanguage
        MediaPipeSpeechVoices.forVoice(target.voiceId)?.let { tuningConfiguration.apply(tuning, it.dictionaryLanguage) }
        model.voiceReplyPolicy = target.responsePolicy
    }
    fun acceptedVoicePolicy(identity: VoiceMessageIdentity): VoiceResponsePolicy? {
        val run = model.agentRunsById.value[identity.runId] ?: return null
        if (run.chatId != room.id || run.assistantMessageId != identity.messageId) return null
        return model.groupedMessages.value.userMessages.firstOrNull { it.id == run.userMessageId && it.chatId == run.chatId }
            ?.timeline?.lastOrNull { it.voiceResponsePolicy != null }?.voiceResponsePolicy
    }

 fun applyAudioConfiguration(){
audio.synthesisSupported = translationMode || backend.backend.forSynthesis(synthesis) == backend.backend
audio.requireLocalOutput = translationMode && translationOutput != null
systemAudio.synthesisLanguageTag = outputSpeechProfile().tag
model.voiceReplyPolicy = VoiceResponsePolicy.forLanguage(outputSpeechProfile().tag, translationMode)
}
    fun readResponse(identity: VoiceMessageIdentity, text: String, includeDetails: Boolean = false) {
        session.holdAudio(benchmarkOwnership.value != null)
        if (benchmarkOwnership.value != null || text.isBlank()) return
        pauseCapture()
        session.access(enabled && preferencesApplied && loaded && roomReady && backend.loaded, permission, lifecycle.currentState.isAtLeast(Lifecycle.State.RESUMED))
        fun begin() {
            if (session.beginMessage(identity.key, manual = true, diagnosticRunId = identity.runId.ifBlank { identity.key }, includeDetails = includeDetails)) {
                playback.manual(identity)
                manualMessage = true
                activeMessage = identity
                retainMessage(identity)
                session.reply(identity.key, text)
            }
        }
        val policy = acceptedVoicePolicy(identity)
        if (translationMode && policy == null) {
            session.fail("The saved reply's language is still unavailable. Wait for the conversation to finish loading before replaying.", reportFailure = false)
            return
        }
        val target = translationPlaybackTarget(policy, translationPair)
        if (translationMode && policy?.translationOnly == true) {
            if (target == null) {
                session.fail("This saved reply uses a language outside the selected translation pair. Select its language in Translation languages before replaying.", reportFailure = false)
                return
            }
            session.pause("translation_replay_preparing")
            val owner = session.playbackPreparationOwner()
            val ticket = ++translationReplayGeneration
            settingsScope.launch {
                try {
                    val factory = translationFactories[translationVoiceKey(target)] ?: backendOwner.translationFactory(target.targetLanguage, target.voiceId)
                    currentCoroutineContext().ensureActive()
                    if (ticket != translationReplayGeneration || !session.ownsPlaybackPreparation(owner) || lifecycle.currentState != Lifecycle.State.RESUMED || settingsOpen || routeOpen || benchmarkOwnership.value != null) return@launch
                    applyTranslationOutput(target, factory)
                    begin()
                } catch (cancelled: CancellationException) {
                    throw cancelled
                } catch (_: Exception) {
                    if (ticket == translationReplayGeneration && session.ownsPlaybackPreparation(owner)) {
                        session.fail("Install the Pocket Multilingual voice pack in Translation languages to replay this translation.", reportFailure = false)
                    }
                }
            }
        } else {
            translationReplayGeneration++
            if (translationMode) {
                translationOutput = null
                audio.requireLocalOutput = false
                kokoroOutput?.configureEngine(backend.factory)
                systemAudio.synthesisLanguageTag = activeSpeechProfile().tag
            }
            begin()
        }
    }

 fun automatic(candidate:VoiceMessageReply):Boolean {
            if (translationMode && candidate.readAloud) {
                // Message and run flows can publish separately. Missing source metadata is
                // not evidence that this is ordinary speech in the previous output language.
                val policy = acceptedVoicePolicy(candidate.identity) ?: return false
                if (policy.translationOnly) {
                    val acceptedOutput = translationOutput?.takeIf { it.target.responsePolicy == policy }
                    val target = acceptedOutput?.target ?: translationPlaybackTarget(policy, translationPair)
                    val factory = acceptedOutput?.factory ?: target?.let { translationFactories[translationVoiceKey(it)] }
                    // Preparation cannot consume this generation or open the previous language's voice.
                    if (target == null || factory == null) return false
                    applyTranslationOutput(target, factory)
                } else {
                    translationOutput = null
                    audio.requireLocalOutput = false
                    kokoroOutput?.configureEngine(backend.factory)
                    systemAudio.synthesisLanguageTag = activeSpeechProfile().tag
                }
            }

return true
}
 fun attach(){
val selectedOutputFactory = if (translationMode) translationOutput?.factory ?: backend.factory else backend.factory
kokoroOutput?.configureEngine(selectedOutputFactory)
audio.requireLocalOutput = translationMode && translationOutput != null
systemAudio.synthesisLanguageTag=outputSpeechProfile().tag
}
 fun available():Boolean {
    val available = !benchmarkRunning &&
        enabled &&
        preferencesApplied &&
        loaded &&
        roomReady &&
        (if (translationMode) translationModel?.status == LocalVoiceModelStatus.READY else backend.speechModelReady(kokoroModel))

return available
}
}

package dev.chungjungsoo.gptmobile.presentation.ui.voice
import dev.chungjungsoo.gptmobile.data.voice.*
import java.io.File
